script:
const D=[{"key": "T01", "scope": "ВЕДУЩИЙ · ПОДГОТОВКА", "title": "Режим партии", "body": "Семь раундов. Выберите режим до первой раздачи.", "rows": [["Первая партия · выбрано", "Испытания отсчитывают раунды. Их эффекты и зачёт отключены."], ["Обычная партия", "Семь из одиннадцати испытаний выбираются в закрытом порядке. Личное указание видит только адресат."]], "actions": ["Сохранить режим", "Назад"]}, {"key": "T02", "scope": "ЛИЧНОЕ ИСПЫТАНИЕ · АДАПТАЦИЯ", "title": "Дойдите до Обиталища", "body": "Пример адаптации испытания. Обиталище — выбранное вами пустое место. Когда окажетесь там, отправьте сообщение Ведущему.", "rows": [["Телефон остаётся при вас", "Ведущий не определяет местоположение. Подтвердите действие после прибытия."]], "actions": ["Я в Обиталище", "Не могу выполнить"], "mobile": true}, {"key": "T03", "scope": "ЛИЧНОЕ ИСПЫТАНИЕ · АДАПТАЦИЯ", "title": "Возвращайтесь к столу", "body": "В этом испытании можно вернуться до общего призыва. Запомните вымышленный адрес: Дом у старых ворот.", "rows": [["Затем вернитесь в Обиталище", "Ничего не переносите. Сообщите отдельно о приходе к столу и о повторном посещении."]], "actions": ["Я у стола", "Сообщить о препятствии"], "mobile": true}, {"key": "T04", "scope": "ЛИЧНОЕ ИСПЫТАНИЕ · ОТЧЁТ", "title": "Вы снова в Обиталище?", "body": "Сообщите, удалось ли вернуться на то же место после посещения стола.", "rows": [["Отчёт о повторном визите", "Ответ будет сверён с предыдущими записями. Один отчёт сам по себе не начисляет шаг."]], "actions": ["Да, я вернулся", "Нет, не получилось"], "mobile": true}, {"key": "T05", "scope": "ВЕДУЩИЙ · СВЕРКА ИСПЫТАНИЯ", "title": "Проверьте последовательность", "body": "Личное условие закрыто. Сверьте только заявленные физические действия.", "rows": [["Посещение → стол → повторное посещение", "Последний отчёт задержался. Подтверждение относится к этой записи, а не к общему результату."], ["0–1 открытое / 2 открытых", "Ведущий применяет предусмотренный карточкой исход. Точный критерий и момент выбора ветки требуют сверки с оригиналом."]], "actions": ["Отклонить запись", "Подтвердить запись"]}, {"key": "T06", "scope": "ВЕДУЩИЙ · ИТОГ ИСПЫТАНИЯ", "title": "Адресат недоступен", "body": "Связь с игроком потеряна. Уточните, было ли действие выполнено. Задание и цель остаются закрытыми.", "rows": [["Не выдавайте новое испытание после события", "Если проверка не разрешит случай, исход остаётся на разборе до решения по оригинальной карточке."]], "actions": ["Вернуться к сверке"]}, {"key": "D01", "scope": "ЛИЧНАЯ МИССИЯ · АВТОРСКИЙ ПРИМЕР", "title": "Подношение без предметов", "body": "Дойдите до согласованного пустого Обиталища. Остановитесь и тихо скажите «Дом, услышь меня».", "rows": [["Возьмите телефон с собой", "Ничего не оставляйте на месте. Подтвердите только после выполнения условия."]], "actions": ["Я выполнил условие", "Вернуться к карточке"], "mobile": true}, {"key": "D02", "scope": "ЛИЧНАЯ МИССИЯ · ЗАПИСЬ", "title": "Подношение записано", "body": "Вы сообщили, что дошли до Обиталища и произнесли фразу. Запись будет проверена вместе с остальными действиями.", "rows": [["Право на зачёт", "Если вас заразили в рамках этого задания, миссия не засчитывается, даже после освобождения."]], "actions": ["К карточке", "Отменить запись"], "mobile": true}, {"key": "D03", "scope": "ВЕДУЩИЙ · ПОДГОТОВКА", "title": "Три личные записи", "body": "Выберите пустое Обиталище. Ведущий подготовит три случайные цифровые миссии.", "rows": [["Запись 1 · скрыта", "Открывается только адресату."], ["Запись 2 · скрыта", "Открывается только адресату."], ["Запись 3 · скрыта", "Открывается только адресату."]], "actions": ["Подтвердить подготовку", "Назад"]}, {"key": "V01", "scope": "РИТУАЛ · СООБЩЕНИЕ", "title": "Какое условие нарушено?", "body": "Выберите открытое прорицание и уточните, что произошло у стола.", "rows": [["Имена стёрты · открыто", "Сообщение: во время обсуждения участник назвал другого игрока по имени."], ["Проверьте исключения", "Личное задание или испытание может иметь приоритет. Техническая помощь и аварийная остановка не считаются нарушением."]], "actions": ["Передать на сверку", "Отмена"]}, {"key": "V02", "scope": "РИТУАЛ · СВЕРКА НАРУШЕНИЯ", "title": "Подтвердить шаг назад?", "body": "Сверьте факт и исключения. Во второй стопке больше всего свечей, поэтому одна возвращается к первой.", "rows": [["0 / 15 / 3 → 1 / 14 / 3", "Останется 34 шага вместо 33. «Имена стёрты» остаётся открытым."], ["Одно нарушение · одно начисление", "После подтверждения можно пропустить движение свечи. Повторный просмотр не меняет результат."]], "actions": ["Отклонить нарушение", "Подтвердить штраф"]}, {"key": "V03", "scope": "РИТУАЛ · ТРЕБУЕТСЯ РЕШЕНИЕ", "title": "Шаг пока не применён", "body": "Размеры стопок равны или самая большая стопка находится слева. Для этого случая нужна сверка исходного правила.", "rows": [["Прогресс сохранён", "Не перемещайте свечу вручную. Подтверждённые успехи и уже открытые условия остаются действующими."]], "actions": ["Вернуться к сверке"]}, {"key": "V04", "scope": "КОМНАТА · ОБЩИЙ РИТУАЛ", "title": "Одно прорицание открыто", "body": "Осталось 34 шага. Открытые условия действуют у ритуального стола.", "rows": [["Имена стёрты · открыто", "1 свеча. Откройте условие."], ["Второе прорицание · закрыто", "14 свечей."], ["Последняя дверь · закрыто", "3 свечи."]], "actions": ["Условие «Имена стёрты»", "В комнату"], "mobile": true}, {"key": "V05", "scope": "КОМНАТА · ОБЩИЙ РИТУАЛ", "title": "Два прорицания открыты", "body": "Осталось 12 шагов. Оба открытых условия действуют у стола одновременно.", "rows": [["Имена стёрты · открыто", "0 свечей."], ["Чужие лица · открыто", "0 свечей."], ["Последняя дверь · закрыто", "12 свечей."]], "actions": ["Первое условие", "Второе условие", "В комнату"], "mobile": true}, {"key": "C01", "scope": "ВЕДУЩИЙ · КАРТОЧКИ", "title": "Допустимые задания", "body": "Согласуйте категории с группой до раздачи. Текущие назначения сохраняются.", "rows": [["✓ Помещение", "Карточки для безопасных мест внутри."], ["✓ Улица", "Задания для согласованной территории снаружи."], ["○ Физический контакт", "Выключено. Включайте только с согласия всей группы."], ["○ Сложные задания", "Выключено. При включении добавляются сложные варианты."]], "actions": ["Применить выбор", "Сбросить изменения"]}, {"key": "C02", "scope": "ВЕДУЩИЙ · ПОРЯДОК РАЗДАЧИ", "title": "Измените порядок участников", "body": "Перемещайте участников стрелками. Первая свободная позиция получает экзорциста, далее роли чередуются.", "rows": [["01 ↑ ↓ Никита", "Экзорцист при новой раздаче."], ["02 ↑ ↓ Анна", "Одержимая при новой раздаче."], ["Сохранённые группы", "Их задания, места и роли не меняются."]], "actions": ["Сохранить порядок", "Отмена"]}, {"key": "C03", "scope": "ВЕДУЩИЙ · ВСТУПЛЕНИЕ", "title": "Выберите историю", "body": "Прочитайте историю всем участникам перед раздачей. Ниже два авторских примера для макета.", "rows": [["✓ Старый дом", "Ночью из закрытой комнаты доносится счёт. Когда вы подходите к двери, голос замолкает."], ["○ Пустой двор", "На знакомой тропе погас последний фонарь. Из темноты кто-то повторил ваши шаги."]], "actions": ["Выбрать историю", "Отмена"]}, {"key": "C04", "scope": "ВЕДУЩИЙ · РАЗДАЧА ИДЁТ", "title": "Настройки раздачи заблокированы", "body": "Участники уже получили карточки. Категории, режим партии и текущий порядок назначений зафиксированы.", "rows": [["Что можно сделать", "До старта замените отдельную неудобную карточку с ноутбука. Неосвобождённая группа сохраняет своё задание."]], "actions": ["К участникам"]}, {"key": "R01", "scope": "РАУНД · СООБЩЕНИЕ ВЕДУЩЕМУ", "title": "Позвать свободных раньше?", "body": "Отметьте, что вы наблюдали во время исследования.", "rows": [["○ Игроки объединились", "Экзорцисты исследуют по одному."], ["○ Долгий разговор", "Короткое общение при встрече разрешено."], ["После подтверждения", "Свободные возвращаются. Пленные и одержимые остаются на местах. Дальше — сверка этого раунда."]], "actions": ["Подтвердить ранний призыв", "Продолжить раунд"]}, {"key": "R02", "scope": "РАУНД · ВОССТАНОВЛЕНИЕ", "title": "Раунд 2 на паузе", "body": "До призыва оставалось 02:18. Задания, группы и прогресс ритуала сохранены.", "rows": [["9 / 6 / 3 свечи · 42 шага", "Возобновление продолжит отсчёт с 02:18. Когда время закончится, к столу вернутся только свободные."]], "actions": ["Продолжить с 02:18", "Оставить на паузе"]}, {"key": "R03", "scope": "СВЕРКА · ОДИН СВОБОДНЫЙ", "title": "Мария может продолжить", "body": "Мария уже за столом. Остальные остаются в своих группах до освобождения.", "rows": [["Одна новая карточка", "Мария получает экзорциста. Остальные назначения и ритуал сохраняются."], ["Отчёт ещё не получен", "По отсутствию связи нельзя объявить полное пленение."]], "actions": ["Раздать Марии", "Уточнить записи"]}, {"key": "E01", "scope": "ЛИЧНЫЕ ДЕЙСТВИЯ · ИСПРАВЛЕНИЕ", "title": "Отменить запись о заражении?", "body": "Запись ещё на сверке. Если участник уже получил задание группы или сообщил об освобождении, нужен разбор связанных действий.", "actions": ["Запросить отмену", "Оставить запись"], "mobile": true}, {"key": "E02", "scope": "ЛИЧНЫЕ ДЕЙСТВИЯ · ИСПРАВЛЕНИЕ", "title": "Отменить запись об освобождении?", "body": "Уточните, выполнено ли условие всей группы. Если участники уже вернулись к столу, Ведущий сверит их отчёты.", "actions": ["Запросить отмену", "Оставить запись"], "mobile": true}, {"key": "E03", "scope": "ВЕДУЩИЙ · СВЯЗАННЫЕ ЗАПИСИ", "title": "Отмена требует сверки", "body": "После заражения появилось групповое освобождение. Отмена первой записи влияет на последующую.", "rows": [["Сверьте обе записи", "Уточните с участниками, кто выполнил условие, кто остался в группе и кто вернулся."], ["Зачёт после решения", "Ритуал обновится один раз после подтверждения всего результата."]], "actions": ["Разобрать записи", "Оставить на сверке"]}, {"key": "E04", "scope": "ЛИЧНЫЙ ИТОГ · РАУНД 2", "title": "Миссия без зачёта", "body": "Вы выполнили миссию, затем были заражены и освобождены. Освобождение позволяет вернуться, но не восстанавливает зачёт прежней миссии.", "rows": [["Групповое освобождение", "Одно очко получает исходное задание группы, включая освобождение нескольких игроков."]], "actions": ["Понятно"], "mobile": true}];
const page=pixso.getNodeById('3:3');
const font=(style)=>({family:'Inter',style});
await Promise.all(['Regular','Medium','Bold'].map(style=>pixso.loadFontAsync(font(style))));
function paint(hex){
  const n=parseInt(hex,16);
  return {type:'SOLID',color:{r:(n>>16)/255,g:((n>>8)&255)/255,b:(n&255)/255}};
}
const palette=Object.fromEntries(Object.entries({canvas:'0D0B12',surface:'17131F',raised:'211B2D',text:'F1EDF7',muted:'B7AFC5',action:'B9A1E8',border:'877597',candle:'D1B783'}).map(([k,v])=>[k,paint(v)]));
const section=pixso.createSection();
section.name='08 · Аудит · испытания, сверка и подготовка';
page.appendChild(section);
section.x=0;
section.y=Math.max(...page.children.filter(n=>n.id!==section.id).map(n=>n.y+n.height))+160;
section.resizeWithoutConstraints(2960,Math.ceil(D.length/4)*790+100);
function stack(name,width,height,fill,pad,gap){
  const node=pixso.createFrame();
  node.name=name;
  node.resize(width,height);
  node.layoutMode='VERTICAL';
  node.primaryAxisSizingMode='FIXED';
  node.counterAxisSizingMode='FIXED';
  node.paddingLeft=node.paddingRight=node.paddingTop=node.paddingBottom=pad;
  node.itemSpacing=gap;
  node.fills=[palette[fill]];
  node.cornerRadius=12;
  node.strokes=[{...palette.border,opacity:.55}];
  return node;
}
function text(parent,content,size,style,color){
  const node=pixso.createText();
  node.name=content.slice(0,50);
  node.fontName=font(style);
  node.fontSize=size;
  node.lineHeight={unit:'PERCENT',value:135};
  node.fills=[palette[color]];
  node.characters=content;
  node.textAutoResize='HEIGHT';
  parent.appendChild(node);
  node.resize(parent.width-parent.paddingLeft-parent.paddingRight,node.height);
  if(node.characters!==content || node.hasMissingFont)throw Error('Invalid text '+node.id);
  return node;
}
const frames=[];
for(const [i,d] of D.entries()){
 const width=d.mobile?390:660;
 const pad=d.mobile?22:30;
 const root=stack(d.key+' · '+d.title,width,d.mobile?720:620,'surface',pad,d.mobile?12:14);
 section.appendChild(root);
 root.x=36+i%4*730;
 root.y=56+Math.floor(i/4)*790;
 text(root,d.scope,12,'Medium','action');
 text(root,d.title,d.mobile?26:30,'Bold','text');
 text(root,d.body,16,'Regular','muted');
 for(const [heading,body] of d.rows??[]){
   const row=stack(heading,width-pad*2,76,'raised',12,4);
   root.appendChild(row);
   row.primaryAxisSizingMode='AUTO';
   text(row,heading,14,'Medium','action');
   text(row,body,14,'Regular','muted');
 }
 const actions=stack('Действия',width-pad*2,52,'surface',0,8);
 root.appendChild(actions);
 actions.strokes=[];
 actions.primaryAxisSizingMode='AUTO';
 for(const [j,caption] of d.actions.entries()){
   const primary=j===0;
   const button=stack('Action / '+caption,actions.width,48,primary?'action':'raised',8,0);
   actions.appendChild(button);
   button.primaryAxisAlignItems='CENTER';
   button.counterAxisAlignItems='CENTER';
   const label=text(button,caption,14,'Medium',primary?'surface':'text');
   label.textAlignHorizontal='CENTER';
 }
 root.primaryAxisSizingMode='AUTO';
 const height=root.height;
 if(height>740)throw Error('Dialog exceeds grid row '+root.name+' '+height);
 frames.push({key:d.key,id:root.id,title:d.title,w:width,h:height});
}
return {verified:frames.every(f=>pixso.getNodeById(f.id).parent.id===section.id),section:section.id,frames};
